export type ExamBoard = 'AQA' | 'Edexcel' | 'OCR' | 'Eduqas' | 'CIE (Cambridge)';

export interface GCSESubject {
  id: string;
  name: string;
  code: string;
  supportedBoards: ExamBoard[];
  icon: string;
  description: string;
  color: string;
}

export interface GCSETopic {
  id: string;
  subjectId: string;
  unitName: string;
  topicName: string;
  tier: 'Foundation' | 'Higher' | 'Both';
  minGrade: number;
  maxGrade: number;
  description: string;
  keyFormulae?: string[];
  examBoards?: ExamBoard[];
  keywords?: string[];
}

export interface SeedQuestion {
  id: string;
  topicId: string;
  gradeLevel: number;
  questionText: string;
  questionType: 'multiple_choice' | 'numerical' | 'text';
  options?: string[];
  correctAnswer: string;
  explanation: {
    overview: string;
    stepByStep: string[];
    keyConcept: string;
    commonMistakes: string[];
    examTip: string;
  };
  markScheme?: string;
}

